-- Instituto Mara — diplomados nuevos (octubre 2026). Se puede repetir.
insert into cursos (id, nombre, descripcion, color, nivel, familia, periodo_tipo, periodo_num, horas, precio, publicado, proximamente, area, tema, dificultad) values
  ('d-seduccion-atraccion', 'Diplomado en Seducción: Psicología de la Atracción y Conexión', 'Aprende a atraer y conectar con honestidad, con base en la ciencia de las relaciones: primeras impresiones, presencia y cuidado personal, seguridad sin arrogancia, conversación y coqueteo respetuoso, autorrevelación, estilos de apego, apps de citas, primeras citas seguras, consentimiento, manejo del rechazo y el paso de conocer a alguien a una relación. Trabajarás con casos mexicanos, 8 laboratorios, un proyecto final y un cuaderno PDF. Para personas adultas de cualquier orientación sexual.', '#BE185D', 'Diplomados', 'Desarrollo humano', null, null, 30, 1690, true, false, null, null, null),
  ('d-imagen-personal', 'Diplomado en Imagen Personal y Estilo', 'Aprende a verte como quieres comunicar, sin reglas rígidas ni juicios sobre el cuerpo: colorimetría con telas y luz natural, proporciones, visagismo, códigos de vestimenta en México, armario cápsula, compras con presupuesto en pesos, cuidado de prendas, imagen en videollamadas y comunicación no verbal. Para personas de cualquier edad, cuerpo e identidad. Con casos mexicanos, 8 laboratorios, un proyecto final de asesoría completa y un cuaderno PDF.', '#B45309', 'Diplomados', 'Desarrollo humano', null, null, 30, 1690, true, false, null, null, null),
  ('d-psicologia-forense', 'Diplomado en Psicología Forense', 'Conoce cómo trabaja la psicología cuando sus conclusiones llegan a un juzgado: el sistema penal acusatorio mexicano, la pericial psicológica de principio a fin, la entrevista forense, los instrumentos y sus límites, la simulación, el testimonio y la memoria, el daño psíquico, la violencia familiar, la custodia, el riesgo de violencia, la prisión y la ética del perito. Trabajarás con casos ficticios mexicanos, 8 laboratorios, un proyecto final y un cuaderno PDF. Para estudiantes y profesionales de la psicología, el derecho, el trabajo social y personas interesadas en el tema.', '#1E3A8A', 'Diplomados', 'Salud y bienestar', null, null, 30, 1690, true, false, null, null, null),
  ('d-lenguaje-corporal', 'Diplomado en Lenguaje Corporal y Comunicación No Verbal', 'Aprende a comunicar con el cuerpo lo que de verdad quieres decir y a interpretar las señales de los demás con prudencia. Recorrerás postura, gestos, rostro, mirada, voz, espacio personal, contacto, tiempo y apariencia; revisarás qué dice la evidencia sobre emociones y primeras impresiones, y desmontarás mitos populares. Practicarás grabándote en video para entrevistas, juntas, ventas, clases, videollamadas y la vida en familia, con casos mexicanos, 8 laboratorios, un proyecto final y un cuaderno PDF. Para cualquier persona adulta.', '#0F766E', 'Diplomados', 'Desarrollo humano', null, null, 30, 1690, true, false, null, null, null),
  ('d-psicologia-influencia', 'Diplomado en Psicología de la Influencia', 'Descubre qué dice la ciencia sobre cómo las personas influyen unas en otras en la vida diaria, el trabajo, las compras, la política y las redes. Estudiarás atajos mentales y sesgos, los principios de Cialdini con su evidencia y sus límites, cambio de actitudes, disonancia, conformidad, obediencia, influencia de minorías, normas sociales, nudges, algoritmos y desinformación. Aprenderás a detectar la influencia, a usarla con ética y a defenderte de su mal uso, con casos mexicanos, 8 laboratorios, un proyecto final y un cuaderno PDF. Para cualquier persona adulta.', '#7C3AED', 'Diplomados', 'Desarrollo humano', null, null, 30, 1690, true, false, null, null, null),
  ('d-leer-personas', 'Diplomado en Cómo Leer a las Personas', 'Aprende a comprender a las personas con precisión y empatía: qué piensan, qué sienten, qué necesitan y cómo deciden. Con lo que dice la investigación sobre precisión empática, sesgos al juzgar, personalidad (los Cinco Grandes), valores y emociones, practicarás un método claro: observar, formular hipótesis, preguntar y verificar, y ajustar. Lo aplicarás con clientes, jefes, equipos, pareja, hijos adolescentes y personas en crisis, con casos mexicanos, 8 laboratorios, un proyecto final y un cuaderno PDF. Para cualquier persona adulta.', '#0369A1', 'Diplomados', 'Desarrollo humano', null, null, 30, 1690, true, false, null, null, null),
  ('d-conversaciones-dificiles', 'Diplomado en Conversaciones Difíciles', 'Aprende a tener las conversaciones que sueles posponer: con tu jefe, tu equipo, tus clientes, tu familia y tu pareja. Con lo que proponen Stone, Patton y Heen, Rosenberg, Gottman y la investigación sobre emociones y retroalimentación, practicarás un método completo: prepararte, regularte, abrir sin atacar, escuchar, decir lo tuyo con claridad, dar malas noticias, poner límites, mediar y cerrar acuerdos que se cumplan. Con casos mexicanos, 8 laboratorios, un proyecto final y un cuaderno PDF. Para cualquier persona adulta.', '#B91C1C', 'Diplomados', 'Desarrollo humano', null, null, 30, 1690, true, false, null, null, null),
  ('d-confianza-seguridad', 'Diplomado en Confianza y Seguridad Personal', 'Construye una confianza real, sin frases mágicas: con lo que dice la investigación sobre autoeficacia, autoestima realista, autocompasión, terapia cognitivo-conductual, síndrome del impostor, exposición gradual, asertividad, valores y hábitos. Aprenderás a callar al crítico interno, a enfrentar el miedo al rechazo paso a paso, a poner límites, a hablar en reuniones y entrevistas y a decidir con incertidumbre. Con casos mexicanos, 8 laboratorios, un proyecto final con tu plan de 30 días y un cuaderno PDF. Para cualquier persona adulta.', '#CA8A04', 'Diplomados', 'Desarrollo humano', null, null, 30, 1690, true, false, null, null, null),
  ('d-manipulacion', 'Diplomado en Psicología de la Manipulación: Cómo Detectarla y Protegerte', 'Aprende a distinguir la influencia legítima de la manipulación y a protegerte de ella. Con lo que dice la investigación sobre chantaje emocional, gaslighting, control coercitivo, acoso laboral, patrones oscuros, ingeniería social, grupos coercitivos y desinformación, practicarás un método para detectar señales, verificar, poner límites, documentar y pedir ayuda en México. Incluye casos de pareja, familia, trabajo, compras y fraudes, 8 laboratorios, un proyecto final y un cuaderno PDF. Para cualquier persona adulta.', '#4C1D95', 'Diplomados', 'Desarrollo humano', null, null, 30, 1690, true, false, null, null, null),
  ('d-negociacion', 'Diplomado en Negociación y Poder de Influencia', 'Aprende a negociar con método y con números: salario y aumentos, compras y proveedores, clientes, renta, la venta de un auto y acuerdos en familia. Con el método de Harvard, la MAAN (BATNA), la zona de posible acuerdo, el anclaje, las concesiones, la escucha táctica y lo que dice la investigación sobre emociones, poder y sesgos, prepararás cada negociación con una plantilla, neutralizarás tácticas duras sin perder la ética y cerrarás acuerdos que se cumplen. Con casos mexicanos, 8 laboratorios, un proyecto final y un cuaderno PDF. Para cualquier persona adulta.', '#0E7490', 'Diplomados', 'Negocios y finanzas', null, null, 30, 1690, true, false, null, null, null),
  ('d-storytelling', 'Diplomado en Storytelling: el arte de contar historias que conectan', 'Aprende a construir historias que se entienden, se recuerdan y mueven a actuar sin manipular. Trabajarás la estructura narrativa (Freytag, el viaje del héroe con sus críticas, la espina de la historia y el ABT de Randy Olson), personajes y detalle sensorial, lo que sí demuestra la investigación sobre transporte narrativo y lo que la neurociencia popular exagera. Luego lo aplicarás a tu historia personal, presentaciones, ventas éticas, liderazgo, datos y redes. Con casos mexicanos, 8 laboratorios, un proyecto final y un cuaderno PDF. Para cualquier persona adulta.', '#C2410C', 'Diplomados', 'Desarrollo humano', null, null, 30, 1690, true, false, null, null, null),
  ('d-psicologia-social', 'Diplomado en Psicología Social para la Vida Real', 'Entiende por qué la gente hace lo que hace cuando hay otros alrededor: cómo se forma tu autoestima, por qué juzgamos rápido, cuándo cedemos ante el grupo o la autoridad, por qué nadie ayuda o casi todos ayudan, de dónde salen el prejuicio, la agresión y la polarización, y qué hacer con todo eso. Revisarás los experimentos clásicos con sus críticas actuales y lo que la crisis de replicación dejó en pie. Con casos mexicanos, 8 laboratorios, un proyecto final y un cuaderno PDF. Para cualquier persona adulta.', '#15803D', 'Diplomados', 'Salud y bienestar', null, null, 30, 1690, true, false, null, null, null),
  ('d-detectar-mentiras', 'Diplomado en Cómo Detectar Mentiras: lo que dice la ciencia', 'Conoce a fondo el trabajo de Paul Ekman (emociones, microexpresiones, filtraciones, el error de Otelo) y contrástalo con lo que hoy muestra la investigación: por qué acertamos poco más que al azar, qué mitos conviene olvidar y qué sí funciona, como las preguntas inesperadas, los detalles verificables y el uso estratégico de la evidencia. Aplicarás todo a la pareja, el trabajo, las ventas, las entrevistas y los fraudes en línea, con casos mexicanos, 8 laboratorios, un proyecto final y un cuaderno PDF. Para cualquier persona adulta.', '#374151', 'Diplomados', 'Salud y bienestar', null, null, 30, 1690, true, false, null, null, null),
  ('d-oratoria', 'Diplomado en Oratoria: hablar en público con seguridad', 'Aprende a hablar en público con seguridad y con algo que valga la pena decir. Trabajarás el miedo escénico con lo que sí tiene evidencia, la retórica clásica aplicada a hoy, el análisis de audiencia, la estructura, la voz, la presencia, las diapositivas, la improvisación y las preguntas difíciles, y prepararás discursos reales: una junta, un pitch de tres minutos, una clase, un brindis o una asamblea vecinal. Con casos mexicanos, 8 laboratorios, un proyecto final con tu discurso grabado y un cuaderno PDF. Para cualquier persona adulta.', '#9F1239', 'Diplomados', 'Desarrollo humano', null, null, 30, 1690, true, false, null, null, null),
  ('d-psicologia-pareja', 'Diplomado en Psicología de la Pareja', 'Conoce lo que la ciencia sabe sobre las relaciones que duran y aplícalo a la tuya: apego adulto, el método Gottman con sus aciertos y sus límites, compromiso, comunicación y conflicto, dinero, sexualidad, llegada de los hijos, suegros, celos, infidelidad, distancia, diversidad de parejas, separación y coparentalidad, además de cómo reconocer la violencia y dónde pedir ayuda. Aprenderás con casos de parejas mexicanas, 8 laboratorios, un proyecto final y un cuaderno PDF. Para personas adultas, con o sin pareja, y para quienes acompañan a otras.', '#A21CAF', 'Diplomados', 'Salud y bienestar', null, null, 30, 1690, true, false, null, null, null),
  ('d-inteligencia-social', 'Diplomado en Inteligencia Social y Carisma', 'Aprende a caer bien sin dejar de ser tú: platicar con desconocidos, hacer preguntas que conectan, escuchar, recordar nombres, usar el humor con cuidado, hacer amistades en la vida adulta y moverte con soltura en fiestas, oficinas, reuniones familiares, redes profesionales y grupos de mensajería. Con lo que muestran Thorndike, Albrecht, Fiske, Antonakis, Epley y la investigación reciente sobre amistad y soledad, entrenarás el carisma como un conjunto de conductas. Con casos mexicanos, 8 laboratorios, un proyecto final y un cuaderno PDF.', '#EA580C', 'Diplomados', 'Desarrollo humano', null, null, 30, 1690, true, false, null, null, null),
  ('d-criminologia', 'Diplomado en Criminología y Perfilación Criminal', 'Entiende por qué ocurre el delito, dónde se concentra y cómo se previene, con teorías clásicas y actuales, criminología ambiental, victimología y datos de México como la ENVIPE y la cifra negra. Conocerás la perfilación criminal sin mitos: su historia, sus métodos, lo que dice la evidencia sobre su eficacia, la perfilación geográfica y la vinculación de casos. Trabajarás con casos ficticios mexicanos, 8 laboratorios, un proyecto final y un cuaderno PDF. Para estudiantes, profesionales de seguridad, derecho, trabajo social y personas curiosas que quieren rigor.', '#7F1D1D', 'Diplomados', 'Salud y bienestar', null, null, 30, 1690, true, false, null, null, null),
  ('d-calidad-lean', 'Diplomado en Calidad y Mejora Continua: Lean, Six Sigma e ISO 9001', 'Aprende a mejorar cualquier proceso con las herramientas que usan las plantas y los servicios más exigentes: costo de la mala calidad, 5S, desperdicios, mapa de flujo de valor, kaizen, SMED, poka-yoke, A3 y 8D, DMAIC, Pareto, gráficas de control, Cp y Cpk en Excel, ISO 9001:2026, auditoría interna y AMEF. Con casos mexicanos de calzado, curtiduría, autopartes, alimentos y servicios, 8 laboratorios, un proyecto final sobre tu propio proceso y un cuaderno PDF. Para supervisores, operarios, ingenieros y mandos.', '#1E40AF', 'Diplomados', 'Negocios y finanzas', null, null, 30, 1890, true, false, null, null, null),
  ('d-datos-ia', 'Diplomado en Análisis de Datos e Inteligencia Artificial para Tomar Decisiones', 'Aprende a convertir datos en decisiones: plantear la pregunta correcta, revisar la calidad y la legalidad de tus datos, limpiar y modelar con Power Query, definir indicadores que no se maquillan, usar estadística para no engañarte, pronosticar midiendo el error, comparar escenarios, apoyarte en la IA generativa sin creerle a ciegas y presentar en Power BI y en un memo de una página. Con casos mexicanos, retos en Excel, 8 laboratorios, un proyecto final con tus propios datos y un cuaderno PDF. Para quien ya usa Excel y quiere decidir mejor.', '#0E7490', 'Diplomados', 'Tecnología', null, null, 30, 1890, true, false, null, null, null),
  ('d-ventas-experiencia', 'Diplomado en Ventas Profesionales y Experiencia del Cliente', 'Aprende a vender ayudando a decidir y a cuidar al cliente para que vuelva y te recomiende: cliente ideal y propuesta de valor, prospección y calificación, conversación de descubrimiento con preguntas SPIN, propuestas con precio total, objeciones y cierre ético, embudo, CRM y pronóstico en Excel, mapa del viaje del cliente, NPS y esfuerzo, posventa y quejas, dentro de la Ley Federal de Protección al Consumidor. Con casos mexicanos, 8 laboratorios, un proyecto final y un cuaderno PDF. Para quien vende o quiere vender.', '#B45309', 'Diplomados', 'Negocios y finanzas', null, null, 30, 1690, true, false, 'Ventas y marketing', 'Ventas y atención', 'desde_cero')
on conflict (id) do update set
  nombre = excluded.nombre, descripcion = excluded.descripcion, color = excluded.color,
  nivel = excluded.nivel, familia = excluded.familia, horas = excluded.horas, precio = excluded.precio,
  publicado = excluded.publicado, proximamente = excluded.proximamente,
  area = coalesce(excluded.area, cursos.area), tema = coalesce(excluded.tema, cursos.tema), dificultad = coalesce(excluded.dificultad, cursos.dificultad);
-- Número de lecciones (regla del 50 % para dejar reseña).
update cursos c set lecciones = v.n from (values
  ('d-seduccion-atraccion', 40),
  ('d-imagen-personal', 40),
  ('d-psicologia-forense', 40),
  ('d-lenguaje-corporal', 40),
  ('d-psicologia-influencia', 40),
  ('d-leer-personas', 40),
  ('d-conversaciones-dificiles', 40),
  ('d-confianza-seguridad', 40),
  ('d-manipulacion', 40),
  ('d-negociacion', 40),
  ('d-storytelling', 40),
  ('d-psicologia-social', 40),
  ('d-detectar-mentiras', 40),
  ('d-oratoria', 40),
  ('d-psicologia-pareja', 40),
  ('d-inteligencia-social', 40),
  ('d-criminologia', 40),
  ('d-calidad-lean', 40),
  ('d-datos-ia', 40),
  ('d-ventas-experiencia', 40)
) as v(id, n) where c.id = v.id;
-- Programas recomendados por giro a los prospectos (empresas).
-- d-calidad-lean: recomendado a Manufactura de calzado, Curtiduría / proveeduría de piel, Industria / manufactura.
update prospectos set cursos_ids = coalesce(cursos_ids[1:2], '{}') || array['d-calidad-lean'] || coalesce(cursos_ids[3:], '{}')
 where segmento in ('Manufactura de calzado', 'Curtiduría / proveeduría de piel', 'Industria / manufactura') and not ('d-calidad-lean' = any(coalesce(cursos_ids, '{}')));
-- d-datos-ia: recomendado a Despacho contable / fiscal, Industria / manufactura, Coworking / oficinas ejecutivas, Agencia de marketing digital.
update prospectos set cursos_ids = coalesce(cursos_ids[1:2], '{}') || array['d-datos-ia'] || coalesce(cursos_ids[3:], '{}')
 where segmento in ('Despacho contable / fiscal', 'Industria / manufactura', 'Coworking / oficinas ejecutivas', 'Agencia de marketing digital') and not ('d-datos-ia' = any(coalesce(cursos_ids, '{}')));
-- d-ventas-experiencia: recomendado a Concesionaria automotriz, Inmobiliaria, Aseguradora / agencia de seguros, Boutique de ropa, Hotelería, Call center.
update prospectos set cursos_ids = coalesce(cursos_ids[1:2], '{}') || array['d-ventas-experiencia'] || coalesce(cursos_ids[3:], '{}')
 where segmento in ('Concesionaria automotriz', 'Inmobiliaria', 'Aseguradora / agencia de seguros', 'Boutique de ropa', 'Hotelería', 'Call center') and not ('d-ventas-experiencia' = any(coalesce(cursos_ids, '{}')));
